     1	import 'package:dcql/dcql.dart';
     2	
     3	/// A verifier's request for a presentation, in the OpenID4VP shape:
     4	/// who is asking (`client_id`), a `nonce`, and a DCQL query.
     5	class PresentationRequest {
     6	  const PresentationRequest({
     7	    required this.clientId,
     8	    required this.nonce,
     9	    required this.dcqlQuery,
    10	    this.responseUri,
    11	  });
    12	
    13	  factory PresentationRequest.fromJson(Map<String, dynamic> json) {
    14	    final clientId = json['client_id'];
    15	    final nonce = json['nonce'];
    16	    final query = json['dcql_query'];
    17	    if (clientId is! String || clientId.isEmpty) {
    18	      throw const FormatException('Presentation request has no client_id');
    19	    }
    20	    if (nonce is! String || nonce.isEmpty) {
    21	      throw const FormatException('Presentation request has no nonce');
    22	    }
    23	    if (query is! Map<String, dynamic>) {
    24	      throw const FormatException('Presentation request has no dcql_query');
    25	    }
    26	    final responseUri = json['response_uri'];
    27	    return PresentationRequest(
    28	      clientId: clientId,
    29	      nonce: nonce,
    30	      dcqlQuery: DcqlCredentialQuery.fromJson(query),
    31	      responseUri: responseUri is String ? Uri.parse(responseUri) : null,
    32	    );
    33	  }
    34	
    35	  final String clientId;
    36	  final String nonce;
    37	  final DcqlCredentialQuery dcqlQuery;
    38	  final Uri? responseUri;
    39	
    40	  /// The domain a presentation for this request is addressed to.
    41	  String get domain => clientId;
    42	
    43	  Map<String, dynamic> toJson() => {
    44	    'client_id': clientId,
    45	    'nonce': nonce,
    46	    'dcql_query': dcqlQuery.toJson(),
    47	    if (responseUri != null) 'response_uri': responseUri.toString(),
    48	  };
    49	}
