     1	/// One salted claim the holder can reveal: its digest sits in the credential.
     2	class Disclosure {
     3	  const Disclosure({
     4	    required this.salt,
     5	    required this.name,
     6	    required this.value,
     7	  });
     8	
     9	  factory Disclosure.fromJson(Object? json) {
    10	    if (json is Map<String, dynamic>) {
    11	      return Disclosure(
    12	        salt: json['salt'] as String,
    13	        name: json['name'] as String,
    14	        value: json['value'],
    15	      );
    16	    }
    17	    if (json is List && json.length == 3) {
    18	      return Disclosure(
    19	        salt: json[0] as String,
    20	        name: json[1] as String,
    21	        value: json[2],
    22	      );
    23	    }
    24	    throw FormatException('Unrecognised disclosure: $json');
    25	  }
    26	
    27	  final String salt;
    28	  final String name;
    29	  final Object? value;
    30	
    31	  Map<String, dynamic> toJson() => {'salt': salt, 'name': name, 'value': value};
    32	}
